//! SplatNet 3 token generation.
//!
//! This is the post-Nintendo-Account portion of the login flow used by s3s:
//! Nintendo `id_token` -> Coral `Account/Login` -> Coral
//! `Game/GetWebServiceToken` -> SplatNet `bullet_tokens`.
//!
//! The `f` value required by Coral is generated by a configurable provider.
//! The default is the public imink-compatible endpoint used by s3s. The
//! nxapi-compatible endpoint is supported as well and requires its own OAuth
//! client id; no provider credential is stored in this repository.

use base64::{engine::general_purpose, Engine as _};
use regex::Regex;
use serde_json::{json, Value};
use url::Url;

use crate::nintendo_auth::NintendoIdentity;

pub const SPLATNET_URL: &str = "https://api.lp1.av5ja.srv.nintendo.net";
pub const DEFAULT_F_GENERATION_URL: &str = "https://api.imink.app/f";
pub const DEFAULT_NXAPI_F_GENERATION_URL: &str = "https://nxapi-znca-api.fancy.org.uk/api/znca/f";
pub const NXAPI_CLIENT_VERSION: &str = "d8fAZDPzwimzQ7c6";
const ZNC_URL: &str = "https://api-lp1.znc.srv.nintendo.net";
const NXAPI_AUTH_URL: &str = "https://nxapi-auth.fancy.org.uk/api/oauth/token";
const NXAPI_AUTH_SCOPE: &str = "ca:gf ca:er ca:dr";
const WEB_VIEW_VERSION_FALLBACK: &str = "10.0.0-88706e32";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SplatNetAuthConfig {
    pub f_generation_url: String,
    pub nxapi_client_id: Option<String>,
    pub client_version: String,
    pub app_user_agent: String,
}

impl Default for SplatNetAuthConfig {
    fn default() -> Self {
        Self {
            f_generation_url: DEFAULT_F_GENERATION_URL.to_owned(),
            nxapi_client_id: None,
            client_version: env!("CARGO_PKG_VERSION").to_owned(),
            app_user_agent: "Mozilla/5.0 (Linux; Android 14; Pixel 7a) AppleWebKit/537.36 Chrome/120.0.6099.230 Mobile Safari/537.36".to_owned(),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SplatNetTokens {
    pub game_web_token: String,
    pub bullet_token: String,
    pub language: String,
    pub country: String,
    pub nso_app_version: String,
    pub web_view_version: String,
}

#[derive(Debug, Clone)]
struct FGeneration {
    value: String,
    request_id: String,
    timestamp: i64,
    encrypted_body: Option<Vec<u8>>,
}

struct SplatNetClient<'a> {
    http: reqwest::Client,
    config: &'a SplatNetAuthConfig,
    nso_app_version: String,
}

impl<'a> SplatNetClient<'a> {
    async fn new(config: &'a SplatNetAuthConfig) -> Result<Self, String> {
        let http = reqwest::Client::builder()
            .user_agent(&config.app_user_agent)
            .build()
            .map_err(|error| format!("创建网络客户端失败: {error}"))?;
        let nso_app_version = fetch_nso_app_version(&http, config).await?;
        Ok(Self {
            http,
            config,
            nso_app_version,
        })
    }

    async fn generate_f(
        &self,
        token: &str,
        hash_method: u8,
        account_id: &str,
        coral_user_id: Option<&str>,
        encrypt_url: Option<&str>,
        encrypt_parameter: Option<&Value>,
    ) -> Result<FGeneration, String> {
        let endpoint = &self.config.f_generation_url;
        let mut body = json!({
            "token": token,
            "hash_method": hash_method,
            "na_id": account_id,
        });
        if let Some(coral_user_id) = coral_user_id {
            body["coral_user_id"] = Value::String(coral_user_id.to_owned());
        }
        if is_nxapi_endpoint(endpoint) {
            if let (Some(url), Some(parameter)) = (encrypt_url, encrypt_parameter) {
                body["encrypt_token_request"] = json!({
                    "url": url,
                    "parameter": parameter,
                });
            }
        }

        let mut last_error = None;
        for _ in 0..3 {
            let mut request = self
                .http
                .post(endpoint)
                .header(
                    "User-Agent",
                    format!("splat3-streaming-widget/{}", self.config.client_version),
                )
                .header("Content-Type", "application/json; charset=utf-8")
                .header("Accept", "application/json")
                .header("X-znca-Platform", "Android")
                .header("X-znca-Version", &self.nso_app_version)
                .json(&body);
            if is_nxapi_endpoint(endpoint) {
                request = request
                    .header(
                        "Authorization",
                        format!(
                            "Bearer {}",
                            nxapi_auth_token(&self.http, self.config).await?
                        ),
                    )
                    .header("X-znca-Client-Version", NXAPI_CLIENT_VERSION);
            }

            let response = request
                .send()
                .await
                .map_err(|error| format!("f 参数服务请求失败: {error}"))?;
            let status = response.status();
            let response_text = response
                .text()
                .await
                .map_err(|error| format!("f 参数服务响应读取失败: {error}"))?;
            let response_json: Value = serde_json::from_str(&response_text)
                .map_err(|error| format!("f 参数服务返回了无效 JSON（HTTP {status}）：{error}"))?;
            if !status.is_success() {
                return Err(provider_error(
                    "f 参数服务",
                    status.as_u16(),
                    &response_json,
                ));
            }
            if response_json.get("error").and_then(Value::as_str) == Some("timeout") {
                last_error = Some("f 参数服务超时".to_owned());
                continue;
            }

            return parse_f_generation_response(&response_json);
        }

        Err(last_error.unwrap_or_else(|| "f 参数服务请求失败".to_owned()))
    }

    async fn coral_request(
        &self,
        access_token: Option<&str>,
        endpoint: &str,
        parameter: Value,
        encrypted_body: Option<Vec<u8>>,
    ) -> Result<Value, String> {
        let mut request = self
            .http
            .post(endpoint)
            .header("X-Platform", "Android")
            .header("X-ProductVersion", &self.nso_app_version)
            .header("Accept", "application/json")
            .header(
                "User-Agent",
                format!("com.nintendo.znca/{}(Android/12)", self.nso_app_version),
            );
        if let Some(access_token) = access_token {
            request = request.header("Authorization", format!("Bearer {access_token}"));
        }

        let is_encrypted = encrypted_body.is_some();
        let response = if let Some(encrypted_body) = encrypted_body {
            request
                .header("Content-Type", "application/octet-stream")
                .header("Accept", "application/octet-stream, application/json")
                .body(encrypted_body)
                .send()
                .await
        } else {
            request
                .header("Content-Type", "application/json; charset=utf-8")
                .json(&json!({ "parameter": parameter }))
                .send()
                .await
        }
        .map_err(|error| format!("Nintendo Coral 请求失败: {error}"))?;

        let status = response.status();
        let response_bytes = response
            .bytes()
            .await
            .map_err(|error| format!("Nintendo Coral 响应读取失败: {error}"))?;
        if !status.is_success() {
            let value = serde_json::from_slice::<Value>(&response_bytes).unwrap_or(Value::Null);
            return Err(provider_error("Nintendo Coral", status.as_u16(), &value));
        }

        if is_encrypted {
            decrypt_coral_response(&self.http, self.config, &response_bytes).await
        } else {
            serde_json::from_slice(&response_bytes)
                .map_err(|error| format!("Nintendo Coral 返回了无效 JSON：{error}"))
        }
    }

    async fn fetch_bullet_token(
        &self,
        game_web_token: &str,
        language: &str,
        country: &str,
    ) -> Result<(String, String), String> {
        let web_view_version = fetch_web_view_version(
            &self.http,
            game_web_token,
            language,
            country,
            &self.config.app_user_agent,
        )
        .await;
        let response = self
            .http
            .post(format!("{SPLATNET_URL}/api/bullet_tokens"))
            .header("Accept-Language", language)
            .header("User-Agent", &self.config.app_user_agent)
            .header("X-Web-View-Ver", &web_view_version)
            .header("X-NACOUNTRY", country)
            .header("Accept", "*/*")
            .header("Origin", SPLATNET_URL)
            .header("X-Requested-With", "com.nintendo.znca")
            .header("Cookie", format!("_gtoken={game_web_token}; _dnt=1"))
            .send()
            .await
            .map_err(|error| format!("SplatNet bullet token 请求失败: {error}"))?;
        let status = response.status();
        if status == reqwest::StatusCode::NO_CONTENT {
            return Err("该 Nintendo Account 尚未使用 Splatoon 3 在线服务".to_owned());
        }
        let response_text = response
            .text()
            .await
            .map_err(|error| format!("SplatNet bullet token 响应读取失败: {error}"))?;
        let response_json: Value = serde_json::from_str(&response_text).unwrap_or(Value::Null);
        if status == reqwest::StatusCode::UNAUTHORIZED {
            return Err("SplatNet game web token 无效或已过期".to_owned());
        }
        if status == reqwest::StatusCode::FORBIDDEN {
            return Err("SplatNet 客户端版本已过期，请稍后更新应用".to_owned());
        }
        if !status.is_success() {
            return Err(provider_error(
                "SplatNet bullet token",
                status.as_u16(),
                &response_json,
            ));
        }
        let bullet_token = required_string(
            &response_json,
            "bulletToken",
            "SplatNet 响应缺少 bulletToken",
        )?;
        Ok((bullet_token, web_view_version))
    }
}

/// Exchanges a Nintendo identity for the two credentials needed by SplatNet.
pub async fn exchange_splatnet_tokens(
    identity: &NintendoIdentity,
    config: &SplatNetAuthConfig,
) -> Result<SplatNetTokens, String> {
    let client = SplatNetClient::new(config).await?;
    let language = identity
        .language
        .as_deref()
        .filter(|value| !value.is_empty())
        .unwrap_or("en-US")
        .to_owned();
    let country = identity
        .country
        .as_deref()
        .filter(|value| !value.is_empty())
        .unwrap_or("US")
        .to_owned();

    let login_url = format!("{ZNC_URL}/v4/Account/Login");
    let login_parameter = json!({
        "f": "",
        "language": language,
        "naBirthday": &identity.birthday,
        "naCountry": &country,
        "naIdToken": &identity.id_token,
        "requestId": "",
        "timestamp": 0,
    });
    let login_f = client
        .generate_f(
            &identity.id_token,
            1,
            &identity.account_id,
            None,
            Some(&login_url),
            Some(&login_parameter),
        )
        .await?;
    let login_request_parameter = add_f_fields(login_parameter, &login_f, None);
    let splatoon_token = match client
        .coral_request(
            None,
            &login_url,
            login_request_parameter.clone(),
            login_f.encrypted_body.clone(),
        )
        .await
    {
        Ok(value) => value,
        Err(_) => {
            client
                .coral_request(
                    None,
                    &login_url,
                    login_request_parameter,
                    login_f.encrypted_body,
                )
                .await?
        }
    };
    let coral_access_token = nested_string(
        &splatoon_token,
        &["result", "webApiServerCredential", "accessToken"],
        "Nintendo Coral 未返回 web service credential",
    )?;
    let coral_user_id = nested_string(
        &splatoon_token,
        &["result", "user", "id"],
        "Nintendo Coral 未返回用户 id",
    )?;

    let service_url = format!("{ZNC_URL}/v4/Game/GetWebServiceToken");
    let service_parameter = json!({
        "f": "",
        "id": 4834290508791808_i64,
        "registrationToken": "",
        "requestId": "",
        "timestamp": 0,
    });
    let service_f = client
        .generate_f(
            &coral_access_token,
            2,
            &identity.account_id,
            Some(&coral_user_id),
            Some(&service_url),
            Some(&service_parameter),
        )
        .await?;
    let service_request_parameter =
        add_f_fields(service_parameter, &service_f, Some(&coral_access_token));
    let service_response = match client
        .coral_request(
            Some(&coral_access_token),
            &service_url,
            service_request_parameter.clone(),
            service_f.encrypted_body.clone(),
        )
        .await
    {
        Ok(value) => value,
        Err(_) => {
            client
                .coral_request(
                    Some(&coral_access_token),
                    &service_url,
                    service_request_parameter,
                    service_f.encrypted_body,
                )
                .await?
        }
    };
    let game_web_token = nested_string(
        &service_response,
        &["result", "accessToken"],
        "Nintendo Coral 未返回 SplatNet game web token",
    )?;
    let (bullet_token, web_view_version) = client
        .fetch_bullet_token(&game_web_token, &language, &country)
        .await?;

    Ok(SplatNetTokens {
        game_web_token,
        bullet_token,
        language,
        country,
        nso_app_version: client.nso_app_version,
        web_view_version,
    })
}

fn add_f_fields(
    mut parameter: Value,
    generated: &FGeneration,
    registration_token: Option<&str>,
) -> Value {
    let object = parameter
        .as_object_mut()
        .expect("SplatNet Coral parameter must be an object");
    object.insert("f".to_owned(), Value::String(generated.value.clone()));
    object.insert(
        "requestId".to_owned(),
        Value::String(generated.request_id.clone()),
    );
    object.insert("timestamp".to_owned(), Value::from(generated.timestamp));
    if let Some(registration_token) = registration_token {
        if object.contains_key("registrationToken") {
            object.insert(
                "registrationToken".to_owned(),
                Value::String(registration_token.to_owned()),
            );
        }
    }
    parameter
}

async fn fetch_nso_app_version(
    http: &reqwest::Client,
    config: &SplatNetAuthConfig,
) -> Result<String, String> {
    let url = sibling_endpoint(&config.f_generation_url, "config")?;
    let mut request = http.get(url).header("Accept", "application/json").header(
        "User-Agent",
        format!("splat3-streaming-widget/{}", config.client_version),
    );
    if is_nxapi_endpoint(&config.f_generation_url) {
        request = request.header(
            "Authorization",
            format!("Bearer {}", nxapi_auth_token(http, config).await?),
        );
    }
    let response = request
        .send()
        .await
        .map_err(|error| format!("获取 Nintendo Switch Online 版本失败: {error}"))?;
    let status = response.status();
    let value: Value = response
        .json()
        .await
        .map_err(|error| format!("Nintendo Switch Online 版本响应无效: {error}"))?;
    if !status.is_success() {
        return Err(provider_error("Nintendo 版本服务", status.as_u16(), &value));
    }
    required_string(&value, "nso_version", "版本服务缺少 nso_version")
}

async fn nxapi_auth_token(
    http: &reqwest::Client,
    config: &SplatNetAuthConfig,
) -> Result<String, String> {
    let client_id = config
        .nxapi_client_id
        .as_deref()
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| "当前 f-generation 服务需要 nxapi client id".to_owned())?;
    let response = http
        .post(NXAPI_AUTH_URL)
        .header("Accept", "application/json")
        .form(&[
            ("grant_type", "client_credentials"),
            ("client_id", client_id),
            ("scope", NXAPI_AUTH_SCOPE),
        ])
        .send()
        .await
        .map_err(|error| format!("nxapi 授权请求失败: {error}"))?;
    let status = response.status();
    let value: Value = response
        .json()
        .await
        .map_err(|error| format!("nxapi 授权响应无效: {error}"))?;
    if !status.is_success() {
        return Err(provider_error("nxapi 授权", status.as_u16(), &value));
    }
    required_string(&value, "access_token", "nxapi 授权响应缺少 access_token")
}

async fn decrypt_coral_response(
    http: &reqwest::Client,
    config: &SplatNetAuthConfig,
    response_bytes: &[u8],
) -> Result<Value, String> {
    let endpoint = sibling_endpoint(&config.f_generation_url, "decrypt-response")?;
    let mut request = http
        .post(endpoint)
        .header("Content-Type", "application/json")
        .header("Accept", "text/plain")
        .header(
            "User-Agent",
            format!("splat3-streaming-widget/{}", config.client_version),
        )
        .json(&json!({
            "data": general_purpose::STANDARD.encode(response_bytes),
        }));
    if is_nxapi_endpoint(&config.f_generation_url) {
        request = request.header(
            "Authorization",
            format!("Bearer {}", nxapi_auth_token(http, config).await?),
        );
    }
    let response = request
        .send()
        .await
        .map_err(|error| format!("解密 Nintendo Coral 响应失败: {error}"))?;
    let status = response.status();
    let response_text = response
        .text()
        .await
        .map_err(|error| format!("解密响应读取失败: {error}"))?;
    if !status.is_success() {
        return Err(format!("解密 Nintendo Coral 响应失败（HTTP {status}）"));
    }
    let value: Value = serde_json::from_str(&response_text)
        .map_err(|error| format!("解密服务返回了无效 JSON：{error}"))?;
    if let Some(data) = value.get("data").and_then(Value::as_str) {
        return serde_json::from_str(data)
            .map_err(|error| format!("解密后的 Nintendo Coral 响应无效：{error}"));
    }
    Ok(value)
}

async fn fetch_web_view_version(
    http: &reqwest::Client,
    game_web_token: &str,
    language: &str,
    country: &str,
    user_agent: &str,
) -> String {
    let home = http
        .get(SPLATNET_URL)
        .header("Accept", "*/*")
        .header("X-AppColorScheme", "DARK")
        .header("X-Requested-With", "com.nintendo.znca")
        .header("Accept-Language", language)
        .header("Cookie", format!("_gtoken={game_web_token}; _dnt=1"))
        .header("User-Agent", user_agent)
        .send()
        .await;
    let Ok(home) = home else {
        return WEB_VIEW_VERSION_FALLBACK.to_owned();
    };
    if !home.status().is_success() {
        return WEB_VIEW_VERSION_FALLBACK.to_owned();
    }
    let Ok(html) = home.text().await else {
        return WEB_VIEW_VERSION_FALLBACK.to_owned();
    };
    let Ok(script_regex) = Regex::new(r#"<script[^>]+src=[\"']([^\"']*static[^\"']*)[\"']"#) else {
        return WEB_VIEW_VERSION_FALLBACK.to_owned();
    };
    let Some(script_path) = script_regex
        .captures_iter(&html)
        .filter_map(|captures| captures.get(1).map(|match_| match_.as_str()))
        .next()
    else {
        return WEB_VIEW_VERSION_FALLBACK.to_owned();
    };
    let Ok(home_url) = Url::parse(SPLATNET_URL) else {
        return WEB_VIEW_VERSION_FALLBACK.to_owned();
    };
    let Ok(script_url) = home_url.join(script_path) else {
        return WEB_VIEW_VERSION_FALLBACK.to_owned();
    };
    let Ok(script_response) = http
        .get(script_url)
        .header("Accept", "*/*")
        .header("Referer", SPLATNET_URL)
        .header("X-Requested-With", "com.nintendo.znca")
        .header("Accept-Language", language)
        .header("X-NACOUNTRY", country)
        .header("Cookie", format!("_gtoken={game_web_token}; _dnt=1"))
        .header("User-Agent", user_agent)
        .send()
        .await
    else {
        return WEB_VIEW_VERSION_FALLBACK.to_owned();
    };
    if !script_response.status().is_success() {
        return WEB_VIEW_VERSION_FALLBACK.to_owned();
    }
    let Ok(script) = script_response.text().await else {
        return WEB_VIEW_VERSION_FALLBACK.to_owned();
    };
    let Ok(version_regex) = Regex::new(
        r#"\b(?P<revision>[0-9a-f]{40})\b[\s\S]*?void 0[\s\S]*?\"revision_info_not_set\"\}`,.*?=`(?P<version>\d+\.\d+\.\d+)-"#,
    ) else {
        return WEB_VIEW_VERSION_FALLBACK.to_owned();
    };
    let Some(captures) = version_regex.captures(&script) else {
        return WEB_VIEW_VERSION_FALLBACK.to_owned();
    };
    let Some(version) = captures.name("version") else {
        return WEB_VIEW_VERSION_FALLBACK.to_owned();
    };
    let Some(revision) = captures.name("revision") else {
        return WEB_VIEW_VERSION_FALLBACK.to_owned();
    };
    format!("{}-{}", version.as_str(), &revision.as_str()[..8])
}

fn is_nxapi_endpoint(endpoint: &str) -> bool {
    endpoint.starts_with("https://nxapi-znca-api.fancy.org.uk/")
}

fn sibling_endpoint(endpoint: &str, child: &str) -> Result<String, String> {
    let url = Url::parse(endpoint).map_err(|error| format!("f-generation URL 无效: {error}"))?;
    let mut path = url.path().to_owned();
    path.truncate(path.rfind('/').unwrap_or(0) + 1);
    let mut sibling = url;
    sibling.set_path(&format!("{path}{child}"));
    Ok(sibling.to_string())
}

fn decode_urlsafe_base64(value: &str) -> Result<Vec<u8>, String> {
    let mut padded = value.to_owned();
    padded.push_str(&"=".repeat((4 - padded.len() % 4) % 4));
    general_purpose::URL_SAFE
        .decode(&padded)
        .or_else(|_| general_purpose::STANDARD.decode(&padded))
        .map_err(|error| format!("f 参数服务返回了无效加密数据: {error}"))
}

fn required_string(value: &Value, key: &str, error: &str) -> Result<String, String> {
    value
        .get(key)
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .ok_or_else(|| error.to_owned())
}

fn nested_string(value: &Value, path: &[&str], error: &str) -> Result<String, String> {
    let mut current = value;
    for key in path {
        current = current.get(*key).ok_or_else(|| error.to_owned())?;
    }
    match current {
        Value::String(value) if !value.is_empty() => Ok(value.clone()),
        Value::Number(value) => Ok(value.to_string()),
        _ => Err(error.to_owned()),
    }
}

fn provider_error(service: &str, status: u16, value: &Value) -> String {
    let detail = ["error", "reason", "message", "error_description"]
        .into_iter()
        .find_map(|key| value.get(key).and_then(Value::as_str))
        .unwrap_or("服务返回错误");
    format!("{service}失败（HTTP {status}）：{detail}")
}

fn parse_f_generation_response(value: &Value) -> Result<FGeneration, String> {
    if value.get("error").and_then(Value::as_bool) == Some(true)
        || value.get("error").and_then(Value::as_str).is_some()
    {
        let detail = ["reason", "message", "error_description", "error"]
            .into_iter()
            .find_map(|key| {
                value.get(key).and_then(|value| match value {
                    Value::String(text) => Some(text.clone()),
                    Value::Bool(value) => Some(value.to_string()),
                    _ => None,
                })
            })
            .unwrap_or_else(|| "服务返回错误".to_owned());
        return Err(format!("f 参数服务返回错误：{detail}"));
    }

    let value_token = required_string(value, "f", "f 参数服务缺少 f")?;
    let request_id = required_string(value, "request_id", "f 参数服务缺少 request_id")?;
    let timestamp = value
        .get("timestamp")
        .and_then(Value::as_i64)
        .ok_or_else(|| "f 参数服务缺少 timestamp".to_owned())?;
    let encrypted_body = value
        .get("encrypted_token_request")
        .and_then(Value::as_str)
        .map(decode_urlsafe_base64)
        .transpose()?;
    Ok(FGeneration {
        value: value_token,
        request_id,
        timestamp,
        encrypted_body,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn default_provider_is_imink_compatible() {
        let config = SplatNetAuthConfig::default();
        assert_eq!(config.f_generation_url, DEFAULT_F_GENERATION_URL);
        assert!(config.nxapi_client_id.is_none());
    }

    #[test]
    fn sibling_endpoint_replaces_the_last_path_segment() {
        assert_eq!(
            sibling_endpoint("https://api.imink.app/f", "config").unwrap(),
            "https://api.imink.app/config"
        );
        assert_eq!(
            sibling_endpoint(
                "https://nxapi-znca-api.fancy.org.uk/api/znca/f",
                "decrypt-response"
            )
            .unwrap(),
            "https://nxapi-znca-api.fancy.org.uk/api/znca/decrypt-response"
        );
    }

    #[test]
    fn adds_dynamic_coral_fields_without_changing_other_parameters() {
        let parameter = json!({"language": "en-US", "timestamp": 0});
        let generated = FGeneration {
            value: "f-value".to_owned(),
            request_id: "request-id".to_owned(),
            timestamp: 123,
            encrypted_body: None,
        };

        let result = add_f_fields(parameter, &generated, None);
        assert_eq!(result["language"], "en-US");
        assert_eq!(result["f"], "f-value");
        assert_eq!(result["requestId"], "request-id");
        assert_eq!(result["timestamp"], 123);
    }

    #[test]
    fn replaces_registration_token_for_web_service_token_requests() {
        let parameter = json!({"registrationToken": ""});
        let generated = FGeneration {
            value: "f-value".to_owned(),
            request_id: "request-id".to_owned(),
            timestamp: 123,
            encrypted_body: None,
        };

        let result = add_f_fields(parameter, &generated, Some("coral-access-token"));
        assert_eq!(result["registrationToken"], "coral-access-token");
    }

    #[test]
    fn decodes_unpadded_urlsafe_encrypted_payloads() {
        assert_eq!(decode_urlsafe_base64("SGVsbG8").unwrap(), b"Hello");
    }

    #[test]
    fn decodes_standard_base64_encrypted_payloads() {
        assert_eq!(decode_urlsafe_base64("++8=").unwrap(), [251, 239]);
    }

    #[test]
    fn reports_f_provider_errors_instead_of_missing_f() {
        let response = json!({
            "error": true,
            "reason": "Something went wrong."
        });

        let error = parse_f_generation_response(&response).unwrap_err();
        assert!(error.contains("Something went wrong."));
        assert!(!error.contains("缺少 f"));
    }
}
